INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15601, 'តាមស្វ័យសត្យបន្ទាត់ តាមពីរចំណុចផ្សេងគ្នា \(A\) និង \(B\) ក្នុងលំហ គេអាចគូសបន្ទាត់បាន ៖', NULL, '["បានបី", "តែមួយគត់", "បានច្រើនរាប់មិនអស់", "បានពីរ"]', 1, NULL, 1, 'mcq', 'តាមពីរចំណុចផ្សេងគ្នាក្នុងលំហ គេអាចគូសបន្ទាត់បានតែមួយគត់។', 'រូបធរណីមាត្រក្នុងលំហ', 'easy', 1, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15602, 'ក្នុងគំនូសប្លង់កាវ៉ាលីយេ (Cavalier Perspective) នៃរូបធរណីមាត្រក្នុងលំហ ចំពោះទ្រនុងដែលត្រូវបាំងបាត់ពីភ្នែក ត្រូវគូសដោយ ៖', NULL, '["បន្ទាត់ជាប់ក្រាស់", "បន្ទាត់រលក", "បន្ទាត់ដាច់ៗ", "បន្ទាត់ទ្វេ"]', 2, NULL, 1, 'mcq', 'ក្នុងគំនូសប្លង់កាវ៉ាលីយេ ទ្រនុងដែលមើលឃើញគូសដោយបន្ទាត់ជាប់ ហើយទ្រនុងដែលបាំងគូសដោយបន្ទាត់ដាច់ៗ។', 'រូបធរណីមាត្រក្នុងលំហ', 'easy', 1, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15603, 'ការបង្វិលត្រីកោណកែងមួយជុំវិញជ្រុងជាប់មុំកែងរបស់វាមួយ ត្រូវនឹងមុំ \(360^\circ\) បង្កើតបានជាសូលីតឈ្មោះអ្វី?', NULL, '["កោន (Cone)", "ស៊ីឡាំង (Cylinder)", "ស៊្វែ (Sphere)", "ពីរ៉ាមីត (Pyramid)"]', 0, NULL, 1, 'mcq', 'ការបង្វិលត្រីកោណកែងជុំវិញជ្រុងជាប់មុំកែង បង្កើតបានជាកោនបរិវត្ត។', 'រូបធរណីមាត្រក្នុងលំហ', 'easy', 1, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15604, 'បើបន្ទាត់ \(d\) មួយ និងប្លង់ \((P)\) មួយ មានចំណុចរួមពីរផ្សេងគ្នា \(A\) និង \(B\) នោះ ៖', NULL, '["\\(d \\perp (P)\\)", "\\(d \\cap (P) = \\emptyset\\)", "\\(d \\subset (P)\\)", "\\(d \\parallel (P)\\)"]', 2, NULL, 1, 'mcq', 'បើបន្ទាត់មួយមានពីរចំណុចក្នុងប្លង់ នោះគ្រប់ចំណុចទាំងអស់នៃបន្ទាត់ស្ថិតក្នុងប្លង់នោះ (បន្ទាត់ស្ថិតក្នុងប្លង់)។', 'រូបធរណីមាត្រក្នុងលំហ', 'easy', 1, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15605, 'ក្នុងលំហ បន្ទាត់ពីរដែលគ្មានចំណុចរួមផង និងមិនស្របគ្នាផង ហៅថា ៖', NULL, '["បន្ទាត់ត្រួតស៊ីគ្នា", "បន្ទាត់ស្របគ្នា", "បន្ទាត់កាត់គ្នា", "បន្ទាត់ទ្វេរ (Skew lines)"]', 3, NULL, 1, 'mcq', 'បន្ទាត់ទ្វេរ (Skew lines) គឺជាបន្ទាត់ពីរដែលមិនស្ថិតក្នុងប្លង់តែមួយ គ្មានចំណុចរួម និងមិនស្របគ្នា។', 'រូបធរណីមាត្រក្នុងលំហ', 'easy', 1, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15606, 'បើប្លង់ពីរ \((P)\) និង \((Q)\) គ្មានចំណុចរួមសោះ នោះគេថាប្លង់ទាំងពីរ ៖', NULL, '["ស្របគ្នា (\\((P) \\parallel (Q)\\))", "ត្រួតស៊ីគ្នា", "កែងគ្នា", "កាត់គ្នា"]', 0, NULL, 1, 'mcq', 'ប្លង់ពីរដែលគ្មានចំណុចរួម គឺជាប្លង់ស្របគ្នា។', 'រូបធរណីមាត្រក្នុងលំហ', 'easy', 1, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15607, 'បើបន្ទាត់ \(d\) និងប្លង់ \((P)\) គ្មានចំណុចរួមសោះ (\(d \cap (P) = \emptyset\)) នោះគេថា ៖', NULL, '["\\(d \\subset (P)\\)", "\\(d \\cap (P) = \\{O\\}\\)", "\\(d \\parallel (P)\\)", "\\(d \\perp (P)\\)"]', 2, NULL, 1, 'mcq', 'បន្ទាត់មួយស្របនឹងប្លង់មួយ កាលណាពួកវាគ្មានចំណុចរួមសោះ។', 'រូបធរណីមាត្រក្នុងលំហ', 'easy', 1, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15608, 'តាមស្វ័យសត្យប្លង់ គេអាចកំណត់ប្លង់បានតែមួយគត់ កាលណាគេស្គាល់ ៖', NULL, '["បីចំណុចមិនរត់ត្រង់ជួរគ្នា", "ពីរចំណុចផ្សេងគ្នា", "បីចំណុចរត់ត្រង់ជួរគ្នា", "បួនចំណុចរត់ត្រង់ជួរគ្នា"]', 0, NULL, 1, 'mcq', 'តាមបីចំណុចមិនស្ថិតលើបន្ទាត់តែមួយ (មិនរត់ត្រង់ជួរ) គេអាចកំណត់បានប្លង់តែមួយគត់។', 'រូបធរណីមាត្រក្នុងលំហ', 'easy', 1, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15609, 'ក្នុងគំនូសប្លង់កាវ៉ាលីយេ បន្ទាត់ពីរដែលស្របគ្នាក្នុងលំហ ត្រូវបានតំណាងដោយ ៖', NULL, '["បន្ទាត់ពីរប្រសព្វគ្នាក្នុងប្លង់គំនូរ", "បន្ទាត់ពីរកែងគ្នាក្នុងប្លង់គំនូរ", "បន្ទាត់កោង", "បន្ទាត់ពីរស្របគ្នាក្នុងប្លង់គំនូរ"]', 3, NULL, 1, 'mcq', 'លក្ខណៈស្របគ្នានៃបន្ទាត់ក្នុងលំហ ត្រូវបានរក្សាឱ្យនៅតែស្របគ្នានៅលើប្លង់គំនូរ។', 'រូបធរណីមាត្រក្នុងលំហ', 'easy', 1, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15610, 'ការបង្វិលចតុកោណកែងមួយជុំវិញជ្រុងរបស់វាមួយ ត្រូវនឹងមុំ \(360^\circ\) បង្កើតបានជាសូលីតឈ្មោះអ្វី?', NULL, '["ស៊្វែ (Sphere)", "គូប (Cube)", "ស៊ីឡាំង (Cylinder)", "កោន (Cone)"]', 2, NULL, 1, 'mcq', 'ការបង្វិលចតុកោណកែងជុំវិញជ្រុងមួយ បង្កើតបានជាស៊ីឡាំងបរិវត្ត។', 'រូបធរណីមាត្រក្នុងលំហ', 'easy', 1, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15611, 'គេមាន ៤ ចំណុច \(A, B, C, D\) មិនស្ថិតក្នុងប្លង់តែមួយ (ចតុមុខ)។ តើតាម ៤ ចំណុចនេះ កំណត់បានប្លង់ចំនួនប៉ុន្មាន?', NULL, '["5", "3", "6", "4"]', 3, NULL, 2, 'mcq', 'តាម ៤ ចំណុចមិនក្នុងប្លង់តែមួយ កំណត់បាន ៤ ប្លង់គឺ (ABC), (ABD), (ACD), (BCD) ត្រូវនឹង C(4, 3) = 4។', 'រូបធរណីមាត្រក្នុងលំហ', 'medium', 1, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15612, 'គេមាន ៤ ចំណុចក្នុងប្លង់ \((P)\) ដែលគ្មាន ៣ ចំណុចណារត់ត្រង់ជួរគ្នាទេ។ ចំនួនបន្ទាត់ដែលស្ថិតក្នុងប្លង់ \((P)\) កាត់តាមពីរចំណុចគឺ ៖', NULL, '["8", "4", "5", "6"]', 3, NULL, 2, 'mcq', 'ចំនួនបន្ទាត់គូសចេញពី ៤ ចំណុចគឺ C(4, 2) = (4 x 3) / 2 = 6 បន្ទាត់។', 'រូបធរណីមាត្រក្នុងលំហ', 'medium', 1, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15613, 'ក្នុងគូប \(ABCD.EFGH\) មុំរវាងបន្ទាត់ \(AB\) និងបន្ទាត់ \(CG\) គឺស្មើនឹង ៖', NULL, '["\\(0^\\circ\\)", "\\(90^\\circ\\)", "\\(45^\\circ\\)", "\\(60^\\circ\\)"]', 1, NULL, 2, 'mcq', 'ដោយ CG // BF នោះមុំរវាង AB និង CG ស្មើនឹងមុំរវាង AB និង BF ដែលស្មើនឹង 90 ដឺក្រេ (មុខ ABFE ជាការេ)។', 'រូបធរណីមាត្រក្នុងលំហ', 'medium', 1, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15614, 'ក្នុងគូប \(ABCD.EFGH\) បន្ទាត់ប្រសព្វរវាងប្លង់បាត \((ABCD)\) និងប្លង់ចំហៀង \((BCGF)\) គឺ ៖', NULL, '["\\(BF\\)", "\\(AB\\)", "\\(BC\\)", "\\(CD\\)"]', 2, NULL, 2, 'mcq', 'ចំណុច B និង C ជាចំណុចរួមនៃប្លង់ទាំងពីរ ដូច្នេះបន្ទាត់ប្រសព្វគឺ BC។', 'រូបធរណីមាត្រក្នុងលំហ', 'medium', 1, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15615, 'ក្នុងគូប \(ABCD.EFGH\) ប្លង់ដែលស្របទៅនឹងប្លង់បាត \((ABCD)\) គឺប្លង់ ៖', NULL, '["\\((EFGH)\\)", "\\((BCGF)\\)", "\\((CDHG)\\)", "\\((ABFE)\\)"]', 0, NULL, 2, 'mcq', 'ប្លង់ពិដាន (EFGH) ស្របនឹងប្លង់បាត (ABCD) ព្រោះវាគ្មានចំណុចរួមក្នុងលំហ។', 'រូបធរណីមាត្រក្នុងលំហ', 'medium', 1, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15616, 'បន្ទាត់ \(a\) និង \(\Delta\) ជាបន្ទាត់ទ្វេរ (មិនកាត់គ្នា និងមិនស្របគ្នា)។ យក ៣ ចំណុច \(A, B, C\) នៅលើ \(a\)។ ចំនួនប្លង់កំណត់ដោយចំណុចនីមួយៗជាមួយបន្ទាត់ \(\Delta\) គឺ ៖', NULL, '["2", "4", "1", "3"]', 3, NULL, 2, 'mcq', 'ចំណុច A, B, C ស្ថិតនៅក្រៅបន្ទាត់ Delta ដូច្នេះកំណត់បាន ៣ ប្លង់ផ្សេងគ្នាគឺ (A, Delta), (B, Delta), (C, Delta)។', 'រូបធរណីមាត្រក្នុងលំហ', 'medium', 1, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
