INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15619, 'ក្នុងចតុមុខ \(ABCD\) បន្ទាត់ប្រសព្វរវាងប្លង់ \((ABC)\) និងប្លង់ \((ABD)\) គឺ ៖', NULL, '["\\(CD\\)", "\\(AC\\)", "\\(BD\\)", "\\(AB\\)"]', 3, NULL, 2, 'mcq', 'ចំណុច A និង B ស្ថិតក្នុងប្លង់ទាំងពីរ ដូច្នេះប្រសព្វនៃប្លង់ទាំងពីរគឺបន្ទាត់ AB។', 'រូបធរណីមាត្រក្នុងលំហ', 'medium', 1, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15620, 'គេមានបន្ទាត់ស្របគ្នាបី \(d_1 \parallel d_2 \parallel d_3\) ក្នុងប្លង់ \((P)\) និងបន្ទាត់ \(d 
otin (P)\) ស្របនឹងបន្ទាត់ទាំងបី។ ចំនួនប្លង់កំណត់ដោយ \(d\) ជាមួយ \(d_1, d_2, d_3\) គឺ ៖', NULL, '["1", "6", "3", "2"]', 2, NULL, 2, 'mcq', 'បន្ទាត់ពីរស្របគ្នាកំណត់បានប្លង់មួយ។ ដូច្នេះ d ជាមួយ d_1, d_2, d_3 កំណត់បាន ៣ ប្លង់ផ្សេងគ្នា។', 'រូបធរណីមាត្រក្នុងលំហ', 'medium', 1, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
