INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15622, 'បើប្លង់ពីរ \((P)\) និង \((Q)\) ប្រសព្វគ្នាតាមបន្ទាត់ \(\Delta\) ហើយចំណុច \(A \in (P)\) និង \(A \in (Q)\) នោះ ៖', NULL, '["\\(\\Delta \\parallel (Q)\\)", "\\(A \notin \\Delta\\)", "\\(\\Delta \\perp (P)\\)", "\\(A \\in \\Delta\\)"]', 3, NULL, 2, 'mcq', 'ប្រសព្វនៃប្លង់ពីរជាបន្ទាត់ត្រង់តែមួយគត់ ដូច្នេះគ្រប់ចំណុចរួមទាំងអស់នៃប្លង់ទាំងពីរត្រូវតែស្ថិតនៅលើបន្ទាត់ប្រសព្វនោះ។', 'រូបធរណីមាត្រក្នុងលំហ', 'medium', 1, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15623, 'ក្នុងគូប \(ABCD.EFGH\) គូនៃបន្ទាត់ខាងក្រោមណាជាបន្ទាត់ទ្វេរ (Skew lines)?', NULL, '["\\(AB\\) និង \\(EF\\)", "\\(AB\\) និង \\(BF\\)", "\\(AB\\) និង \\(CD\\)", "\\(AB\\) និង \\(CG\\)"]', 3, NULL, 2, 'mcq', 'AB និង CG មិនស្ថិតក្នុងប្លង់តែមួយ មិនកាត់គ្នា និងមិនស្របគ្នា ដូច្នេះជាបន្ទាត់ទ្វេរ។', 'រូបធរណីមាត្រក្នុងលំហ', 'medium', 1, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15624, 'ក្នុងពីរ៉ាមីត \(S.ABCD\) បាតជាចតុកោណកែងដែលមានអង្កត់ទ្រូងប្រសព្វគ្នាត្រង់ \(O\)។ បន្ទាត់ប្រសព្វនៃប្លង់ \((SAC)\) និងប្លង់ \((SBD)\) គឺ ៖', NULL, '["\\(SO\\)", "\\(SA\\)", "\\(SC\\)", "\\(SB\\)"]', 0, NULL, 2, 'mcq', 'ចំណុច S ជាចំណុចរួម ហើយ O = AC ∩ BD ជាចំណុចរួមទីពីរ ដូច្នេះបន្ទាត់ប្រសព្វគឺ SO។', 'រូបធរណីមាត្រក្នុងលំហ', 'medium', 1, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15625, 'ក្នុងគូប \(ABCD.EFGH\) មុំរវាងអង្កត់ទ្រូងមុខ \(AF\) និងអង្កត់ទ្រូងមុខ \(CH\) គឺស្មើនឹង ៖', NULL, '["\\(45^\\circ\\)", "\\(60^\\circ\\)", "\\(90^\\circ\\)", "\\(30^\\circ\\)"]', 1, NULL, 3, 'mcq', 'ដោយ CH // BG នោះមុំរវាង AF និង CH ស្មើនឹងមុំរវាង AF និង BG។ ត្រីកោណ AFG ឬ ABG ... ជាក់ស្តែងក្នុងត្រីកោណសម័ង្ស AFH (AF = FH = AH = a√2) នាំឱ្យមុំស្មើនឹង 60 ដឺក្រេ។', 'រូបធរណីមាត្រក្នុងលំហ', 'hard', 1, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15626, 'ក្នុងចតុមុខ \(ABCD\) គេយក \(M \in AB\) និង \(N \in CD\)។ ទំនាក់ទំនងទីតាំងរវាងបន្ទាត់ \(MN\) និងបន្ទាត់ \(BC\) គឺ ៖', NULL, '["បន្ទាត់ទ្វេរ (Skew lines)", "កាត់គ្នា", "ស្របគ្នា", "ត្រួតស៊ីគ្នា"]', 0, NULL, 3, 'mcq', 'MN និង BC មិនស្ថិតក្នុងប្លង់តែមួយ គ្មានចំណុចរួម និងមិនស្របគ្នា ដូច្នេះជាបន្ទាត់ទ្វេរ។', 'រូបធរណីមាត្រក្នុងលំហ', 'hard', 1, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15627, 'តាម ៦ ចំណុចក្នុងលំហ ដែលគ្មាន ៤ ចំណុចណាក្នុងប្លង់តែមួយ និងគ្មាន ៣ ចំណុចណារត់ត្រង់ជួរ។ ចំនួនប្លង់ដែលកំណត់បានគឺ ៖', NULL, '["15", "24", "18", "20"]', 3, NULL, 3, 'mcq', 'ចំនួនប្លង់គឺ C(6, 3) = (6 x 5 x 4) / (3 x 2 x 1) = 20 ប្លង់។', 'រូបធរណីមាត្រក្នុងលំហ', 'hard', 1, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15628, 'ក្នុងចតុមុខ \(ABCD\) ចំណុច \(B'' \in BD\) និង \(C'' \in CD\) ដែល \(B''C''\) កាត់ \(BC\) ត្រង់ \(E\)។ បន្ទាត់ប្រសព្វនៃប្លង់ \((ABC)\) និង \((AB''C'')\) គឺ ៖', NULL, '["\\(AE\\)", "\\(AB\\)", "\\(AD\\)", "\\(AC\\)"]', 0, NULL, 3, 'mcq', 'A ជាចំណុចរួមស្រាប់ ហើយ E = BC ∩ B''C'' ជាចំណុចរួមទីពីរ ដូច្នេះបន្ទាត់ប្រសព្វគឺ AE។', 'រូបធរណីមាត្រក្នុងលំហ', 'hard', 1, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15629, 'ក្នុងគូប \(ABCD.EFGH\) មុំរវាងអង្កត់ទ្រូងបាត \(AC\) និងអង្កត់ទ្រូងបាត \(BD\) គឺស្មើនឹង ៖', NULL, '["\\(45^\\circ\\)", "\\(0^\\circ\\)", "\\(90^\\circ\\)", "\\(60^\\circ\\)"]', 2, NULL, 3, 'mcq', 'បាត ABCD ជាការេ ដូច្នេះអង្កត់ទ្រូងទាំងពីរកែងគ្នាត្រង់ចំណុចកណ្តាល នាំឱ្យមុំស្មើនឹង 90 ដឺក្រេ។', 'រូបធរណីមាត្រក្នុងលំហ', 'hard', 1, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15630, 'ក្នុងគូប \(ABCD.EFGH\) បន្ទាត់ប្រសព្វនៃប្លង់អង្កត់ទ្រូងឈរ \((ACGE)\) និងប្លង់ \((BDHF)\) គឺ ៖', NULL, '["អង្កត់ទ្រូង AC", "ទ្រនុង AE", "អង្កត់ទ្រូង BD", "បន្ទាត់តភ្ជាប់ផ្ចិតបាតទាំងពីរ"]', 3, NULL, 3, 'mcq', 'ប្រសព្វនៃប្លង់អង្កត់ទ្រូងឈរទាំងពីរ គឺជាបន្ទាត់អ័ក្សកាត់តាមចំណុចប្រសព្វនៃអង្កត់ទ្រូងបាតទាំងពីរ។', 'រូបធរណីមាត្រក្នុងលំហ', 'hard', 1, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15631, 'ក្នុងពីរ៉ាមីត \(S.ABC\) ប្លង់មួយកាត់ \(SA, SB, SC\) ត្រង់ \(A'', B'', C''\)។ បើ \(A''B'' \cap AB = \{I\}\) និង \(B''C'' \cap BC = \{J\}\) នោះបន្ទាត់ប្រសព្វនៃ \((A''B''C'')\) និងបាត \((ABC)\) គឺ ៖', NULL, '["\\(A''B''\\)", "\\(IJ\\)", "\\(AC\\)", "\\(B''C''\\)"]', 1, NULL, 3, 'mcq', 'I និង J ជារបស់ប្លង់ទាំងពីរ ដូច្នេះបន្ទាត់ប្រសព្វនៃប្លង់ទាំងពីរគឺ IJ។', 'រូបធរណីមាត្រក្នុងលំហ', 'hard', 1, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15632, 'ជើងទម្រម៉ាស៊ីនថតរូប (Camera Tripod) ត្រូវបានរចនាឡើងដោយមានជើង ៣។ តាមទស្សនៈធរណីមាត្រក្នុងលំហ ហេតុអ្វីបានជាជើងទម្រនេះតែងតែមានលំនឹងជាប់ល្អលើគ្រប់ផ្ទៃដីរាបស្មើ?', NULL, '["ព្រោះជើងទាំង ៣ មានប្រវែងស្មើគ្នាជានិច្ច", "ព្រោះតាម ៣ ចំណុចមិនរត់ត្រង់ជួរ តែងតែកំណត់បានប្លង់តែមួយគត់ជានិច្ច", "ព្រោះទំនាញផែនដីទាញជើងទាំង ៣ ស្មើគ្នា", "ព្រោះបន្ទាត់ ៣ តែងតែកែងគ្នាក្នុងលំហ"]', 1, NULL, 3, 'mcq', 'តាមស្វ័យសត្យប្លង់ បីចំណុចមិនរត់ត្រង់ជួរកំណត់បានប្លង់តែមួយគត់ ដូច្នេះចុងជើងទាំង ៣ តែងតែស្ថិតក្នុងប្លង់តែមួយជានិច្ច ធ្វើឱ្យតុឬជើងទម្រមានលំនឹងល្អ។', 'រូបធរណីមាត្រក្នុងលំហ', 'pisa', 1, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15633, 'ជាងឈើដំឡើងទ្វារបន្ទប់មួយដោយប្រើត្រចៀកទ្វារ (Hinges) ពីរគ្រាប់ភ្ជាប់លើស៊ុមទ្វារ។ ហេតុអ្វីបានជាទ្វារអាចបង្វិលបើកបិទបានតាមអ័ក្សតែមួយគត់?', NULL, '["ព្រោះទ្វារស្របនឹងកម្រាលឥដ្ឋ", "ព្រោះប្លង់ទ្វារកាត់ប្លង់ជញ្ជាំងបានមុំ 90 ដឺក្រេ", "ព្រោះទ្វារមានរាងជាចតុកោណកែង", "ព្រោះតាម ២ ចំណុចនៃត្រចៀកទ្វារ កំណត់បានបន្ទាត់អ័ក្សបង្វិលតែមួយគត់"]', 3, NULL, 3, 'mcq', 'តាមស្វ័យសត្យបន្ទាត់ តាមពីរចំណុចកំណត់បានបន្ទាត់តែមួយគត់ ដែលជាអ័ក្សបង្វិលនៃទ្វារ។', 'រូបធរណីមាត្រក្នុងលំហ', 'pisa', 1, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15634, 'ពីរ៉ាមីតគីហ្សា (Giza Pyramid) មានបាតជាការេ \(ABCD\) និងកំពូល \(S\)។ ជ្រុងបាត \(AB\) និងទ្រនុងឈរ \(SC\) ស្ថិតក្នុងទីតាំងធៀបបែបណា?', NULL, '["បន្ទាត់ស្របគ្នា", "បន្ទាត់កាត់គ្នា", "បន្ទាត់ទ្វេរ (Skew lines)", "ស្ថិតក្នុងប្លង់តែមួយ"]', 2, NULL, 3, 'mcq', 'AB និង SC មិនស្ថិតក្នុងប្លង់តែមួយ គ្មានចំណុចរួម និងមិនស្របគ្នា ដូច្នេះវាជាបន្ទាត់ទ្វេរ (Skew lines)។', 'រូបធរណីមាត្រក្នុងលំហ', 'pisa', 1, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15635, 'ធុងកញ្ចក់ចិញ្ចឹមត្រីរាងប្រលេពីប៉ែតកែង \(ABCD.EFGH\)។ ប្លង់កញ្ចក់បាត \((ABCD)\) និងប្លង់គម្របខាងលើ \((EFGH)\) ស្ថិតក្នុងទីតាំងបែបណា?', NULL, '["ប្លង់ស្របគ្នា (\\((ABCD) \\parallel (EFGH)\\))", "ប្លង់ត្រួតស៊ីគ្នា", "ប្លង់ប្រសព្វគ្នា", "ប្លង់កែងគ្នា"]', 0, NULL, 3, 'mcq', 'ផ្ទៃបាត និងផ្ទៃគម្របខាងលើនៃប្រលេពីប៉ែតកែងជាប្លង់ស្របគ្នា ព្រោះគ្មានចំណុចរួម។', 'រូបធរណីមាត្រក្នុងលំហ', 'pisa', 1, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15636, 'ក្នុងបន្ទប់រៀនមួយ កម្រាលឥដ្ឋតំណាងដោយប្លង់ \((P)\) ហើយសសរអគារឈរត្រង់មួយតំណាងដោយបន្ទាត់ \(d\)។ ទំនាក់ទំនងរវាងបន្ទាត់ \(d\) និងប្លង់ \((P)\) គឺ ៖', NULL, '["បន្ទាត់ d ស្របនឹងប្លង់ (P)", "បន្ទាត់ d និងប្លង់ (P) គ្មានទំនាក់ទំនង", "បន្ទាត់ \\(d\\) កាត់ប្លង់ \\((P)\\) ត្រង់គល់សសរមួយចំណុចគត់", "បន្ទាត់ d ស្ថិតនៅក្នុងប្លង់ (P)"]', 2, NULL, 3, 'mcq', 'សសរឈរត្រង់កាត់កម្រាលឥដ្ឋបាតត្រង់គល់សសរមួយចំណុចគត់ ដូច្នេះ d ∩ (P) = {A}។', 'រូបធរណីមាត្រក្នុងលំហ', 'pisa', 1, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15637, 'ចូររៀបរាប់ និងពន្យល់ពីវិធីទាំង ៤ យ៉ាងក្នុងការកំណត់ប្លង់តែមួយគត់ក្នុងលំហ។', NULL, '[]', 0, NULL, 5, 'writing', 'ករណីទី ១ ៖ តាមបីចំណុចមិនស្ថិតលើបន្ទាត់តែមួយ (មិនរត់ត្រង់ជួរ) គេកំណត់បានប្លង់តែមួយគត់ (១ ពិន្ទុ) (1 ពិន្ទុ)
ករណីទី ២ ៖ តាមបន្ទាត់មួយ និងចំណុចមួយនៅក្រៅបន្ទាត់នោះ គេកំណត់បានប្លង់តែមួយគត់ (១ ពិន្ទុ) (1 ពិន្ទុ)
ករណីទី ៣ ៖ តាមបន្ទាត់ពីរប្រសព្វគ្នាត្រង់មួយចំណុច គេកំណត់បានប្លង់តែមួយគត់ (១ ពិន្ទុ) (1 ពិន្ទុ)
ករណីទី ៤ ៖ តាមបន្ទាត់ពីរស្របគ្នា គេកំណត់បានប្លង់តែមួយគត់ (១ ពិន្ទុ) (1 ពិន្ទុ)
សន្និដ្ឋាន ៖ គ្រប់ករណីទាំង ៤ ខាងលើសុទ្ធតែកើតចេញពីស្វ័យសត្យប្លង់គ្រឹះតែមួយ (១ ពិន្ទុ) (1 ពិន្ទុ)', 'រូបធរណីមាត្រក្នុងលំហ', 'easy', 0, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15638, 'គេមាន ៤ ចំណុច \(A, B, C, D\) មិនស្ថិតក្នុងប្លង់តែមួយ។ ចូរបង្ហាញ និងរាប់ចំនួនប្លង់ដែលកំណត់បានដោយ ៤ ចំណុចនេះ។', NULL, '[]', 0, NULL, 5, 'writing', 'កត់សម្គាល់ថា តាម ៣ ចំណុចមិនរត់ត្រង់ជួរ កំណត់បានប្លង់មួយគត់ (១ ពិន្ទុ) (1 ពិន្ទុ)
រាប់ប្លង់ទី ១ និងទី ២ ៖ ប្លង់ (ABC) និងប្លង់ (ABD) (១ ពិន្ទុ) (1 ពិន្ទុ)
រាប់ប្លង់ទី ៣ និងទី ៤ ៖ ប្លង់ (ACD) និងប្លង់ (BCD) (១ ពិន្ទុ) (1 ពិន្ទុ)
ផ្ទៀងផ្ទាត់តាមរូបមន្តបន្សំ ៖ C(4, 3) = 4 ប្លង់ (១ ពិន្ទុ) (1 ពិន្ទុ)
សន្និដ្ឋាន ៖ តាម ៤ ចំណុចមិនក្នុងប្លង់តែមួយ កំណត់បាន ៤ ប្លង់ផ្សេងគ្នាដែលជាមុខនៃចតុមុខ (១ ពិន្ទុ) (1 ពិន្ទុ)', 'រូបធរណីមាត្រក្នុងលំហ', 'medium', 0, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15639, 'គេមាន ៥ ចំណុច \(A, B, C, D, E\) ក្នុងប្លង់ \((P)\) ដែលគ្មាន ៣ ចំណុចណារត់ត្រង់ជួរ។ គណនាចំនួនបន្ទាត់ក្នុងប្លង់ \((P)\) ដែលកាត់តាមពីរចំណុច។', NULL, '[]', 0, NULL, 5, 'writing', 'រំលឹកស្វ័យសត្យ ៖ តាមពីរចំណុចផ្សេងគ្នា គូសបានបន្ទាត់មួយគត់ (១ ពិន្ទុ) (1 ពិន្ទុ)
រំលឹកលក្ខណៈបន្ទាត់ក្នុងប្លង់ ៖ បើពីរចំណុចក្នុង (P) នោះបន្ទាត់ទាំងមូលស្ថិតក្នុង (P) (១ ពិន្ទុ) (1 ពិន្ទុ)
ជ្រើសរើសវិធីគណនា ៖ ប្រើរូបមន្តបន្សំ C(n, 2) សម្រាប់ n = 5 (១ ពិន្ទុ) (1 ពិន្ទុ)
គណនាតម្លៃលេខ ៖ C(5, 2) = (5 x 4) / 2 = 10 បន្ទាត់ (១ ពិន្ទុ) (1 ពិន្ទុ)
សន្និដ្ឋាន ៖ គេអាចគូសបានបន្ទាត់ចំនួន ១០ ដែលស្ថិតនៅក្នុងប្លង់ (P) (១ ពិន្ទុ) (1 ពិន្ទុ)', 'រូបធរណីមាត្រក្នុងលំហ', 'medium', 0, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15640, 'ក្នុងគូប \(ABCD.EFGH\) ចូរកំណត់មុំដែលបង្កើតឡើងដោយបន្ទាត់ \(AB\) និងបន្ទាត់ \(CG\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ពិនិត្យទីតាំងបន្ទាត់ AB និង CG ៖ បន្ទាត់ទាំងពីរមិនស្ថិតក្នុងប្លង់តែមួយទេ (បន្ទាត់ទ្វេរ) (១ ពិន្ទុ) (1 ពិន្ទុ)
រកបន្ទាត់ស្រប ៖ ក្នុងមុខ BCGF បន្ទាត់ BF ស្របនឹង CG (១ ពិន្ទុ) (1 ពិន្ទុ)
ប្តូរមុំ ៖ មុំរវាង AB និង CG ស្មើនឹងមុំរវាង AB និង BF (១ ពិន្ទុ) (1 ពិន្ទុ)
គណនាមុំ ៖ មុខ ABFE ជាការេ នាំឱ្យ AB កែងនឹង BF ពោលគឺមុំស្មើ 90 ដឺក្រេ (១ ពិន្ទុ) (1 ពិន្ទុ)
សន្និដ្ឋាន ៖ មុំរវាងបន្ទាត់ AB និង CG គឺ 90 ដឺក្រេ (បន្ទាត់កែងគ្នា) (១ ពិន្ទុ) (1 ពិន្ទុ)', 'រូបធរណីមាត្រក្នុងលំហ', 'medium', 0, '11SC', 'រូបធរណីមាត្រក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
