INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15642, 'ក្នុងចតុមុខ \(ABCD\) ចំណុច \(B'' \in BD\) និង \(C'' \in CD\) ដែល \(B''C''\) មិនស្របនឹង \(BC\)។ កំណត់បន្ទាត់ប្រសព្វរវាងប្លង់ \((ABC)\) និងប្លង់ \((AB''C'')\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់ចំណុចរួមទីមួយ ៖ ចំណុច A ជាចំណុចរួមនៃប្លង់ទាំងពីរស្រាប់ (១ ពិន្ទុ) (1 ពិន្ទុ)
រកចំណុចប្រសព្វក្នុងបាត ៖ ក្នុងប្លង់ (BCD) បន្ទាត់ B''C'' និង BC កាត់គ្នាត្រង់ E (១ ពិន្ទុ) (1 ពិន្ទុ)
